reversal.fixed_text:
if self.buf.len() == 0 {
    if let StartRecord = self.state {
        self.eof = true;
        return self.next_eoc();
    } else if let EndRecord = self.state {
        self.state = StartRecord;
        return self.next_eor();
    } else {
        self.state = EndRecord;
        return self.next_data();
    }
}

reversal.parent_text:
if self.buf.len() == 0 {
    self.eof = true;
    if let StartRecord = self.state {
        return self.next_eoc();
    } else if let EndRecord = self.state {
        self.state = StartRecord;
        return self.next_eor();
    } else {
        self.state = EndRecord;
        return self.next_data();
    }
}
